\label{thm:main}
Let \(\Omega\subset\mathbb R^2\) be a smooth bounded simply connected domain. There exists a finite constant \(B_\Omega\), depending only on \(\Omega\), such that every solution \(u\in C^2(\overline\Omega)\) of \eqref{eq:pde} satisfies
\begin{equation}\label{eq:main}
 E(u):=\int_\Omega|\nabla u|^2\,\mathrm d x\le B_\Omega.
\end{equation}
Consequently, \(F|_{\mathcal M_\beta}\) has no nonnegative critical point when \(\beta>B_\Omega\).

\label{tool:DTglobal}
Suppose that \(u_j\) satisfies \eqref{eq:pde}, \(\sup_j E_j<\infty\), and \(\gamma_j\to\infty\). Then, along a subsequence,
\(\theta_j\to0\) and \(\sqrt{\theta_j}\gamma_j\to c\in(0,\infty)\).

\label{lem:moment}
The pullback \(v\) satisfies the Pohozaev identity
\begin{equation}\label{eq:weighted-pohozaev}
 \begin{aligned}
 \frac12\int_{\partial\mathbb D}(\partial_n v)^2\,\mathrm d\sigma
 &=\theta\int_\mathbb D\left(a+\frac12z\cdot\nabla a\right)(e^{v^2}-1)\,\mathrm d z\\
 &=\int_\mathbb D gP_\mathbb D\,\mathrm d z.
 \end{aligned}
\end{equation}
Expanding \(-\partial_n v\) in a Fourier series and applying Parseval's identity gives the equivalent form
\begin{equation}\label{eq:moment}
 M^2+2\sum_{n=1}^{\infty}\left|\int_\mathbb D z^n\rho_\mathbb D(z)\,\mathrm d z\right|^2
 =4\pi\int_\mathbb D gP_\mathbb D\,\mathrm d z.
\end{equation}

\label{lem:mass}
Let \(\lambda_1(\Omega)\) be the first Dirichlet eigenvalue of \(-\Delta\) on \(\Omega\). There exists a constant \(C_\Omega\), depending only on \(\Omega\), such that
\begin{equation}\label{eq:massbounds}
 0<\theta<\lambda_1(\Omega),\qquad M\le C_\Omega,
 \qquad M\le\frac{C_\Omega}{\sqrt{\log(1/\theta)}}
 \quad(0<\theta<e^{-2}).
\end{equation}
Consequently, if \(\theta_j\to0\), then \(M_j\to0\) and \(u_j\to0\) in \(L^q(\Omega)\) for every \(1\le q<\infty\).

\label{lem:strip}
Let \(u_j\) be positive solutions of \eqref{eq:pde}, with \(\nu_j,\Pi_j\) defined by \eqref{eq:normalizations}, and write
\(d(x)=\operatorname{dist}(x,\partial\Omega)\). There exist constants \(\delta_0>0\) and \(C_\Omega>0\), depending only on \(\Omega\), such that, for every \(j\) and \(0<\varepsilon<\delta_0\),
\begin{equation}\label{eq:strip}
 \nu_j\{d<\varepsilon\}\le C_\Omega\varepsilon,
 \qquad \Pi_j\{d<\varepsilon\}\le C_\Omega\varepsilon\Pi_j(\Omega).
\end{equation}

\label{lem:jensen}
For every \(0<\alpha<4\pi\),
\begin{equation}\label{eq:globaljensen}
 \int_\Omega e^{\alpha w_j}\,\mathrm d x\le C_{\alpha,\Omega},
\end{equation}
where \(w_j\) is defined in \eqref{eq:normalizations}. Suppose that \(\nu_j\rightharpoonup\nu\), \(B_{2r}(x_0)\Subset\Omega\), and \(\bar p>\nu(\overline B_{2r}(x_0))\). For fixed \(0<\alpha<4\pi\), we then have
\begin{equation}\label{eq:localjensen}
 \int_{B_r(x_0)}e^{(\alpha/\bar p)w_j}\,\mathrm d x\le C_{r,\bar p,\alpha,\Omega}
\end{equation}
for all sufficiently large \(j\). If \(0<L<\alpha/\bar p\), then
\begin{equation}\label{eq:lowheight}
 \nu_j(B_r(x_0)\cap\{s_j\le L\})+
 \Pi_j(B_r(x_0)\cap\{s_j\le L\})\le C_{r,L,\bar p,\alpha,\Omega}\theta_j.
\end{equation}

\label{lem:budget}
Let \(x_j\in K\Subset\Omega\), \(\beta_j=u_j(x_j)\to\infty\), and \(\nabla u_j(x_j)=0\). Assume that
\begin{equation}\label{eq:localassumptions}
 \log\theta_j=o(\beta_j^2),\qquad
 \beta_j(u_j(x_j+\mu_j z)-\beta_j)\to U(z)
 \quad\hbox{in }C^2_{\mathrm{loc}}(\mathbb R^2),
\end{equation}
where \(U\) and \(\mu_j\) are defined in \eqref{eq:Uz-mu_j}.
Suppose that \(\sup_jM_j<\infty\), \(\sup_j\theta_j<\infty\), and
\begin{equation}\label{eq:budget}
 \int_{B_{L_j}(x_j)}u_j\rho_j\,\mathrm d x\longrightarrow4\pi,
 \qquad L_j=e^{-\beta_j^2/32}.
\end{equation}
Then Theorem~\ref{tool:DTlocal} applies with comparison radius
\(d_j=e^{-\beta_j^2/16}\).

\label{lem:matching}
Under the hypotheses of Lemma~\ref{lem:budget}, fix \(\tau\in(1/16,1/2)\) and set
\[
 r_j(\tau)=e^{-\tau\beta_j^2},\qquad
 Q_j(r)=\int_{B_r(x_j)}\rho_j\,\mathrm d x,\qquad
 I_{\mathrm{out},j}(r)=\int_{\Omega\setminus B_r(x_j)}G(x_j,y)\rho_j(y)\,\mathrm d y.
\]
Then
\begin{align}
 Q_j(r_j(\tau))&=\frac{4\pi}{\beta_j}+\frac{4\pi}{\beta_j^3}+o(\beta_j^{-3}),\label{eq:flux}\\
 \log\frac{\theta_j\beta_j^2}{4}
 &=4\pi R(x_j)-1-\beta_j I_{\mathrm{out},j}(r_j(\tau))+o(1),
 \label{eq:matching}
\end{align}
where \(R\) is the Robin function defined in \eqref{eq:green}.

\label{lem:logtheta}
Every sequence of solutions with \(\gamma_j\to\infty\) satisfies
\(\log\theta_j=o(\gamma_j^2)\), where \(\gamma_j\) is defined in \eqref{eq:notation}.

\label{lem:maxbubble}
Suppose that \(u_j(x_j)=\gamma_j\to\infty\), and define \(\mu_j=(\theta_j\gamma_j^2e^{\gamma_j^2})^{-1/2}\). Then
\begin{equation}\label{eq:maxbubble}
 \gamma_j(u_j(x_j+\mu_jz)-\gamma_j)\to U(z)
 \quad\hbox{in }C^2_{\mathrm{loc}}(\mathbb R^2).
\end{equation}
For every fixed \(\sigma\in(0,1/2)\),
\begin{equation}\label{eq:maxbudget}
 \gamma_j\int_{B_{\exp(-\sigma\gamma_j^2)}(x_j)}\rho_j\,\mathrm d x\to4\pi,
 \qquad
 \int_{B_{\exp(-\sigma\gamma_j^2)}(x_j)}u_j\rho_j\,\mathrm d x\to4\pi.
\end{equation}

\label{prop:maxbound}
Every solution satisfies
\begin{equation}\label{eq:maxbound}
 \theta\gamma^2\le C_\Omega,
\end{equation}
and
\begin{equation}\label{eq:logenergy}
 E\le\gamma M\le C'_\Omega\bigl[1+\log^+(1/\theta)\bigr].
\end{equation}
In particular, \(E_j\to\infty\) implies \(\theta_j\to0\).

\label{lem:pressureupper}
Let \(\{a_i\}\) be the set of all atoms of \(\nu\), namely the points for which \(p_i:=\nu(\{a_i\})>0\), and set \(\tau_i:=\Pi(\{a_i\})\). Then
\begin{equation}\label{eq:pressureupper}
 \Pi=\sum_i\tau_i\delta_{a_i},\qquad 0\le\tau_i\le\frac{p_i^2}{4\pi}.
\end{equation}
The set of atoms is at most countable.

\label{lem:stress}
For every \(j\),
\begin{equation}\label{eq:stress}
 \frac1{4\pi}\iint_{\Omega\times\Omega} K_X\,\mathrm d\nu_j\,\mathrm d\nu_j+B_X(\nu_j)
 =\frac12\int_{\Omega}\operatorname{div} X\,\mathrm d\Pi_j.
\end{equation}
The identity also holds for compactly supported Lipschitz vector fields, with divergence understood almost everywhere.

\label{prop:square}
The weak limit \(\Pi\) is given by
\begin{equation}\label{eq:square}
 \Pi=\frac1{4\pi}\sum_i p_i^2\delta_{a_i}.
\end{equation}

\label{prop:height}
Fix an atom \(a\) of mass \(p>0\), and set \(A=4\pi/p\). For every \(\varepsilon>0\),
\begin{equation}\label{eq:height}
 \lim_{r\downarrow0}\limsup_{j\to\infty}
 \nu_j\bigl(B_r(a)\cap\{|s_j-A|>\varepsilon\}\bigr)=0.
\end{equation}
In this limit, \(r\) may be restricted to a sequence tending to zero with \(\nu(\partial B_r(a))=\Pi(\partial B_r(a))=0\). In addition,
\begin{equation}\label{eq:TVheight}
 \lim_{r\downarrow0}\limsup_j
 \left\|\Pi_j-\frac1A\nu_j\right\|_{\operatorname{TV}(B_r(a))}=0.
\end{equation}
The total variation norm is defined in Section~\ref{sec:notation}.

\label{lem:densitypotential}
Let \(f\in L^\infty(\Omega)\), \(0\le f\le D\), and set \(\,\mathrm d\eta=f\,\mathrm d x\), \(m=\eta(\Omega)>0\). Then its Green potential satisfies
\begin{equation}\label{eq:densitypotential}
 \sup_{y\in\Omega}G\eta(y)\le\frac m{4\pi}\left[\log\frac{C_\Omega D}{m}+1\right].
\end{equation}

\label{prop:strict}
Every sequence with \(\theta_j\to0\) satisfies
\begin{equation}\label{eq:strict}
 M_j^2\log(1/\theta_j)\to0,\qquad M_j^2E_j\to0,
 \qquad s_j\to0\quad\hbox{strongly in }H^1_0(\Omega).
\end{equation}

\label{lem:weakclassify}
Let \(A>0\), and let \(\mu\ne0\) be a finite nonnegative nonatomic measure on \(\mathbb R^2\). Suppose that, for every \(X\in C_c^\infty(\mathbb R^2;\mathbb R^2)\),
\begin{equation}\label{eq:planarstress}
 \frac1{4\pi}\iint_{\mathbb R^2\times\mathbb R^2} K_X(z,y)\,\mathrm d\mu(z)\,\mathrm d\mu(y)
 =\frac1{2A}\int_{\mathbb R^2}\operatorname{div} X\,\mathrm d\mu.
\end{equation}
Then
\begin{equation}\label{eq:classdensity}
 \,\mathrm d\mu(z)=\frac4A\,\frac{\lambda^2}{(1+\lambda^2|z-z_0|^2)^2}\,\mathrm d z
 \quad\hbox{for some }\lambda>0,\ z_0\in\mathbb R^2.
\end{equation}

\label{prop:profile}
After passing to a subsequence,
\begin{equation}\label{eq:profile}
 \widehat\nu_j\rightharpoonup\mu\quad\hbox{locally weakly on }\mathbb R^2,\qquad
 \,\mathrm d\mu(z)=\frac{p}{\pi(1+|z|^2)^2}\,\mathrm d z.
\end{equation}
Thus \(\mu(\mathbb R^2)=p\): the total mass of the rescaled limit equals the mass of the atom of \(\nu\) at \(a_0\).

\label{prop:center}
After passing to a subsequence,
\begin{align}
 &A_j\to A,\qquad k_j\to A^{-2},\qquad
 M_j^2\log(1/r_j)\to A^2/2,\label{eq:scalematch}\\
 &W_j\to W(z):=\frac1A\log\frac2{1+|z|^2}
 \quad\hbox{in }L^q_{\mathrm{loc}}(\mathbb R^2)\quad(1\le q<\infty),\label{eq:Wlimit}\\
 &f_j\to\frac{p}{\pi(1+|z|^2)^2}
 \quad\hbox{in }L^1_{\mathrm{loc}}(\mathbb R^2).\label{eq:strongsource}
\end{align}

\label{lem:lowdisk}
Let the disks \(D_j=B_{R_j}(c_j^*)\) lie in a fixed compact subset of \(\Omega\). Suppose that \(u_j\) attains its maximum on \(\overline D_j\) at an interior point \(y_j\), and that
\[
 B_j=u_j(y_j)\to\infty,\qquad
 \sup_{\partial D_j}u_j=o(B_j),\qquad
 \log(1/R_j)=o(B_j^2),\qquad
 \log\theta_j=o(B_j^2).
\]
Assume the uniform upper bounds for the total mass and parameter in Lemma~\ref{lem:mass}. Then
\begin{equation}\label{eq:lowdiskmatch}
 \log\frac{\theta_jB_j^2}{4}
 =4\pi R(y_j)-1
 -B_j\int_{\Omega\setminus B_{\exp(-B_j^2/4)}(y_j)}
 G(y_j,z)\rho_j(z)\,\mathrm d z+o(1).
\end{equation}

\label{prop:representative}
The functions \(W_j,W\) of Proposition~\ref{prop:center} satisfy
\[
 W_j\to W\quad\hbox{in }C^2_{\mathrm{loc}}(\mathbb R^2).
\]
There exist local maximum points \(x_j\to a_0\) of \(u_j\), with \(\beta_j=u_j(x_j)\), such that
\begin{equation}\label{eq:representative}
 M_j\beta_j\to A,\qquad
 \beta_j(u_j(x_j+\mu_jz)-\beta_j)\to U(z)
 \quad\hbox{in }C^2_{\mathrm{loc}}(\mathbb R^2),\qquad
 \mu_j=(\theta_j\beta_j^2e^{\beta_j^2})^{-1/2}.
\end{equation}
Moreover,
\begin{equation}\label{eq:scaleconstants}
 \frac{x_j-b_j}{r_j}\to0,\qquad \frac{\mu_j}{r_j}\to\frac12,\qquad
 \lim_{T\to\infty}\lim_{j\to\infty}
 \nu_j(B_{T\mu_j}(x_j))=p.
\end{equation}

\label{prop:neighborhood}
{Fix \(0<\sigma<A^2/2\), and set \(\varrho_j=e^{-\sigma/M_j^2}\). Then}
\begin{equation}\label{eq:neighborhood}
 \sup_{B_{4{\varrho_j}}(b_j)}u_j\le C_\sigma/M_j,\qquad
 \nu_j(B_{2{\varrho_j}}(b_j))\to p,\qquad
 \int_{B_{2{\varrho_j}}(b_j)}u_j\rho_j\,\mathrm d x\to4\pi.
\end{equation}
In particular, the local maximum points selected in Proposition~\ref{prop:representative} satisfy all the hypotheses of Lemma~\ref{lem:budget}.
